async ({ shell: { execFile } }) => {
  await new Promise((res) => setTimeout(res, 15000));
  const l = await execFile("gh", ["run", "list", "--workflow", "release.yml", "--limit", "1", "--json", "databaseId,headBranch,status"]);
  const id = JSON.parse(l.stdout)[0]?.databaseId;
  const w = await execFile("gh", ["run", "watch", String(id), "--exit-status", "--interval", "10"], { timeoutMs: 250000 });
  return { list: l.stdout, code: w.code, out: w.stdout.slice(-800) };
}
